import Link from "next/link";
import projects from "./projects.json";

const Index = () => (
  <div>
    <h1>Projects</h1>
    <ul>
      {Object.entries(projects).map((value, key) => {
        return (
          <li key={key}>
            <Link>
              <a href="/projects">{value[0]}</a>
            </Link>
          </li>
        );
      })}
    </ul>
  </div>
);

export default Index;
